/**
 * Keratin Graph: a finite, source-positioned graphing and compatibility workbench.
 *
 * Original directed predications come from the existing feather-graph reader.
 * Stalk state alphabets, contact admissibility tables, lock exclusions,
 * explicit face attachments, proposed unfilled boundary loops, and observer
 * scopes are application-supplied. None are source-generated by this module.
 * This is a typed downstream finite sheaf *model*, not a causal black-hole
 * constructor, a proof of a physical keratin material, or the native
 * Articulating -> object-language predication bridge (Obsmetrologia #79).
 *
 * The underlying exact cellular 2-complex and ranks are delegated to the
 * existing SignGraph cohomology engine. A declared candidate boundary is
 * NEVER inserted as a face in the actual complex.
 */
import { featherGraphOfPredications, featherSourceFields, featherSourceArray } from './feather-graph.mjs';
import { cellular2Complex } from './cohomology.mjs';
import { apply, coboundary, cochain, cellularSheaf, cellularSheafCohomology } from './cellular-sheaf.mjs';
import { readingOfSides } from '@red-cup-engineering/computer-data-engineering-services-section/four';

const freeze = Object.freeze;
const isRecord = x => x !== null && typeof x === 'object' && !Array.isArray(x);
const named = x => typeof x === 'string' && x.length > 0;
const ordered = (a,b) => a < b ? -1 : a > b ? 1 : 0;
const frozen = values => freeze([...values]);
const admitted = new WeakSet();
const analysisOwners = new WeakMap();
const linearOwners = new WeakMap();
const MAX_POSITIONS = 128, MAX_RELATIONS = 256, MAX_FACES = 32;
const MAX_HOLES = 32, MAX_LOCKS = 512, MAX_OBSERVERS = 8;
const MAX_STATES = 16, MAX_ALLOWED_PAIRS = 256;
const DEFAULT_ASSIGNMENT_BUDGET = 250000;

const fail = message => { throw new TypeError(`keratin graph: ${message}`); };
// Feather is the earliest lawful source-position reader. Reuse that SAME
// inert-record and dense-array admission in its downstream Keratin workbench
// while preserving existing Keratin-specific error reports and resource caps.
const fields = (record, keys, context) => featherSourceFields(record, keys, context, fail);
const sourceArray = (values, context, maximum = 256) =>
  featherSourceArray(values, context, maximum, fail);
function unique(xs, context) {
  const set = new Set(xs);
  if (set.size !== xs.length) fail(`${context}: duplicate identity`);
  return set;
}
const requireName = (x, context) => { if (!named(x)) fail(`${context}: nonempty source identity required`); return x; };
const nameList = (xs, context, max = 256, {allowEmpty = false} = {}) => {
  if (!Array.isArray(xs) || xs.length > max || (!allowEmpty && xs.length === 0))
    fail(`${context}: invalid named list or exceeded work limit`);
  sourceArray(xs, context, max);
  if(!xs.every(named))
    fail(`${context}: invalid named list or exceeded work limit`);
  unique(xs, context);
  return frozen(xs);
};

/** The exact SourcePosition key already used by SignGraph's feather reader. */
export function keratinPositionKey(performed, side = 'token') {
  requireName(performed, 'performed');
  if (!['token','claim'].includes(side)) fail('position side must be token or claim');
  return JSON.stringify([performed,side]);
}

function boundaryWalk(raw, byOccurrence, label) {
  if (!Array.isArray(raw) || raw.length < 1 || raw.length > MAX_RELATIONS)
    fail(`${label}: requires a bounded nonempty list of oriented source occurrences`);
  sourceArray(raw, label, MAX_RELATIONS);
  const steps = raw.map((sourceStep, i) => {
    const step=fields(sourceStep,['occurrence','direction'],`${label} step ${i}`);
    if (!byOccurrence.has(step.occurrence) || ![1,-1].includes(step.direction))
      fail(`${label}: each oriented step must reference an original occurrence with sign +/-1`);
    return freeze({edge: step.occurrence, direction: step.direction});
  });
  return frozen(steps);
}

function limit(value, maximum, label) {
  if (!Array.isArray(value) || value.length > maximum) fail(`${label}: list exceeds work limit ${maximum}`);
  sourceArray(value, label, maximum);
}

/**
 * Build a finite material interpretation OF original directed predications.
 * The interpreter does not invent contacts, faces or the boundary of a hole.
 * Every source relation must receive an explicit ordered allowed-pairs table.
 */
export function keratinGraphOfPredications(input = {}) {
  const given=fields(input,['source','selectors','stalks','contacts','faces','holes','locks','observers'],'graph input');
  const {source, selectors, stalks, contacts, faces = [], holes = [], locks = [], observers = []}=given;
  const feather = featherGraphOfPredications(source, selectors);
  if (feather.positions.length > MAX_POSITIONS || feather.predications.length > MAX_RELATIONS)
    fail('source positions/relations exceed keratin graph resource budget');
  limit(stalks, MAX_POSITIONS, 'stalks');
  limit(contacts, MAX_RELATIONS, 'contacts');
  limit(faces, MAX_FACES, 'faces'); limit(holes, MAX_HOLES, 'holes');
  limit(locks, MAX_LOCKS, 'locks'); limit(observers, MAX_OBSERVERS, 'observers');

  const positions = new Map(feather.positions.map(p => [p.key,p]));
  const occurrences = new Map(feather.predications.map(e => [e.occurrence,e]));
  const stalkMap = new Map();
  for (const sourceStalk of stalks) {
    const s=fields(sourceStalk,['position','states'],'stalk');
    if (!positions.has(s.position) || stalkMap.has(s.position)) fail('stalk refers to unknown or repeated original position');
    stalkMap.set(s.position,freeze({position:s.position,states:nameList(s.states,'stalk states',MAX_STATES)}));
  }
  if (stalkMap.size !== positions.size) fail('every original position must have exactly one stalk');

  const contactMap = new Map();
  for (const sourceContact of contacts) {
    const c=fields(sourceContact,['occurrence','allowed'],'contact');
    const edge = occurrences.get(c.occurrence);
    if (!edge || contactMap.has(c.occurrence)) fail('contact must identify one unique original source predication');
    if (!Array.isArray(c.allowed) || c.allowed.length > MAX_ALLOWED_PAIRS)
      fail('contact admissibility must be a bounded array of ordered state pairs');
    sourceArray(c.allowed, 'contact admissibility', MAX_ALLOWED_PAIRS);
    const a = new Set(stalkMap.get(edge.subject).states);
    const b = new Set(stalkMap.get(edge.object).states);
    const seen = new Set();
    const pairs = c.allowed.map(pair => {
      if (!Array.isArray(pair) || pair.length !== 2)
        fail(`contact ${c.occurrence}: pair must belong to ordered endpoint stalks`);
      sourceArray(pair, 'directed contact pair', 2);
      if (!a.has(pair[0]) || !b.has(pair[1]))
        fail(`contact ${c.occurrence}: pair must belong to ordered endpoint stalks`);
      const key = JSON.stringify(pair);
      if (seen.has(key)) fail('duplicate directed admissibility pair');
      seen.add(key);
      return frozen(pair);
    });
    contactMap.set(c.occurrence, freeze({occurrence:c.occurrence,sourceRecord:edge.sourceRecord,
      from:edge.subject,to:edge.object,allowed:frozen(pairs)}));
  }
  if (contactMap.size !== occurrences.size) fail('every original relation needs an explicit compatibility table');

  const seenEventIds = new Set();
  const lockLog = locks.map((sourceLock,i) => {
    const lock=fields(sourceLock,['id','position','sourceRecord','excludes'],'lock');
    const {id,position,sourceRecord} = lock;
    requireName(id,'lock id'); requireName(sourceRecord,'lock sourceRecord');
    if (!positions.has(position)) fail('lock cannot introduce a new source position');
    if (seenEventIds.has(id)) fail('lock event IDs must be unique');
    seenEventIds.add(id);
    const excludes = nameList(lock.excludes,`lock ${id} excludes`,MAX_STATES,{allowEmpty:true});
    if (excludes.some(value=>!stalkMap.get(position).states.includes(value)))
      fail('lock exclusions must be values of an original stalk');
    return freeze({id,position,sourceRecord,excludes,order:i});
  });

  const edges = feather.predications.map(e => freeze({id:e.occurrence,from:e.subject,to:e.object}));
  const vertices = feather.positions.map(p => p.key);
  const faceIds = new Set(), faceRecords=[];
  for (const sourceFace of faces) {
    const face=fields(sourceFace,['id','sourceRecord','boundary'],'face');
    requireName(face.id,'face id'); requireName(face.sourceRecord,'face sourceRecord');
    if (faceIds.has(face.id)) fail('duplicate filled face');
    faceIds.add(face.id);
    faceRecords.push(freeze({id:face.id,sourceRecord:face.sourceRecord,
      boundary:boundaryWalk(face.boundary,occurrences,`face ${face.id}`)}));
  }
  const topology = cellular2Complex({vertices,edges,faces:faceRecords});
  const holeRecords=[];
  const holeIds = new Set();
  for (const sourceHole of holes) {
    const hole=fields(sourceHole,['id','sourceRecord','boundary'],'hole candidate');
    requireName(hole.id,'hole id'); requireName(hole.sourceRecord,'hole sourceRecord');
    if (faceIds.has(hole.id) || holeIds.has(hole.id)) fail('candidate hole IDs must be distinct from actual faces');
    holeIds.add(hole.id);
    const boundary = boundaryWalk(hole.boundary,occurrences,`hole ${hole.id}`);
    // The *probe* fills this loop only to assess its independent H1 class.
    // Its result is never substituted for the actual topology.
    const probe = cellular2Complex({vertices,edges,faces:[...faceRecords,{id:hole.id,boundary}]});
    const rankContribution = topology.betti.h1 - probe.betti.h1;
    if (![0,1].includes(rankContribution)) fail('unexpected rank of candidate loop');
    holeRecords.push(freeze({id:hole.id,sourceRecord:hole.sourceRecord,boundary,
      individuallyIndependentH1:rankContribution === 1,
      reading:rankContribution ? 'candidate-unfilled-nontrivial-cycle' : 'homologically-redundant-boundary',
    }));
  }
  const withHypotheticalFills = holes.length ? cellular2Complex({
    vertices,edges,faces:[...faceRecords,...holeRecords.map(h=>({id:h.id,boundary:h.boundary}))],
  }) : topology;
  const aggregateIndependentBoundaries = topology.betti.h1 - withHypotheticalFills.betti.h1;

  const observerIds = new Set();
  const observerRecords=observers.map(sourceObserver => {
    const observer=fields(sourceObserver,['id','visiblePositions','visibleOccurrences'],'observer');
    requireName(observer.id,'observer id');
    if (observerIds.has(observer.id)) fail('duplicate observer');
    observerIds.add(observer.id);
    const visiblePositions = nameList(observer.visiblePositions,'visible positions',MAX_POSITIONS,{allowEmpty:true});
    const vp = new Set(visiblePositions);
    if (visiblePositions.some(p => !positions.has(p))) fail('observer has unknown source position');
    const visibleOccurrences = nameList(observer.visibleOccurrences,'visible occurrences',MAX_RELATIONS,{allowEmpty:true});
    if (visibleOccurrences.some(e => {
      const relation=occurrences.get(e);
      return !relation || !vp.has(relation.subject) || !vp.has(relation.object);
    })) fail('observer cannot see a relation without both endpoint positions');
    return freeze({id:observer.id,visiblePositions,visibleOccurrences,
      qualification:'caller-declared visibility, not a derived physical light cone'});
  });

  const graph=freeze({
    kind:'signgraph.keratinGraph.finiteFiberHoleReading.v1',
    feather,
    stalks:frozen([...stalkMap.values()].sort((a,b)=>ordered(a.position,b.position))),
    contacts:frozen([...contactMap.values()].sort((a,b)=>ordered(a.occurrence,b.occurrence))),
    locks:frozen(lockLog),
    filledFaces:frozen(faceRecords),
    candidateHoles:frozen(holeRecords),
    topology,
    aggregateIndependentBoundaries,
    observers:frozen(observerRecords),
    status:'downstream finite model; not proven source-to-keratin or causal shroud transport',
  });
  admitted.add(graph);
  return graph;
}

/**
 * A separate exact linear (vector-stalk) reading on the SAME original graph.
 * Each restriction is a caller-supplied matrix; original directed edge IDs
 * and source position keys are reused. Delegates all linear sheaf arithmetic
 * to SignGraph's existing `cellularSheaf` and `cellularSheafCohomology`.
 *
 * `H1` here is graph-only cellular SHEAF H1. It is distinct from the H1 of
 * a filled two-complex: 2-cell sheaf extension remains the existing open
 * SignGraph #17/Obsmetrologia receiving obligation, not a hidden inference.
 */
export function keratinLinearSheaf(graph, options = {}) {
  if(!admitted.has(graph))fail('linear sheaf requires original in-process graph');
  // Read source options before destructuring. Getter-backed properties must not
  // execute in order to propose a stalk or restriction matrix.
  const qualified=fields(options,['vertexStalks','relationStalks'],'linear sheaf options');
  const {vertexStalks,relationStalks}=qualified;
  if(!Array.isArray(vertexStalks)||!Array.isArray(relationStalks))
    fail('linear sheaf requires vertexStalks and relationStalks');
  // These are source assertions, not an invitation to iterate arbitrary
  // Array subclasses, getters, decorated arrays, or unlimited dimensions.
  sourceArray(vertexStalks,'linear vertex stalks',MAX_POSITIONS);
  sourceArray(relationStalks,'linear relation stalks',MAX_RELATIONS);
  const vertices=new Map(graph.feather.positions.map(p=>[p.key,null]));
  for(const sourceVertex of vertexStalks){
    const v=fields(sourceVertex,['position','dim'],'linear vertex stalk');
    if(!vertices.has(v.position)||vertices.get(v.position)!==null)fail('linear vertex stalk must occur once on an original position');
    if(!Number.isSafeInteger(v.dim)||v.dim<1||v.dim>16)fail('linear stalk dimension must be 1..16');
    vertices.set(v.position,freeze({id:v.position,dim:v.dim}));
  }
  if([...vertices.values()].some(x=>x===null))fail('linear sheaf missing original vertex stalk');
  const pred=new Map(graph.feather.predications.map(e=>[e.occurrence,e]));
  const edges=new Map();
  for(const sourceContact of relationStalks) {
    const c=fields(sourceContact,['occurrence','dim','restrict'],'linear edge stalk');
    if(!pred.has(c.occurrence)||edges.has(c.occurrence))fail('linear contact must be one original predication');
    if(!Number.isSafeInteger(c.dim)||c.dim<1||c.dim>16)fail('linear edge dimension must be 1..16');
    const restrict=fields(c.restrict,['from','to'],'linear restriction matrices');
    const original=pred.get(c.occurrence);
    edges.set(c.occurrence,{id:c.occurrence,from:original.subject,to:original.object,
      dim:c.dim,restrict});
  }
  if(edges.size!==pred.size)fail('linear sheaf missing original directed relation');
  const sheaf=cellularSheaf({vertices:[...vertices.values()],edges:[...edges.values()]});
  const reading=freeze({kind:'signgraph.keratinGraph.linearSheafReading.v1',
    sheaf,cohomology:sheaf.exact?cellularSheafCohomology(sheaf):null,
    sourceOccurrences:frozen([...pred.values()].map(p=>freeze({occurrence:p.occurrence,sourceRecord:p.sourceRecord}))),
    qualification:'original edge identities retained; linear restrictions supplied; exact H1 belongs to graph sheaf only, not a filled surface or physical keratin',
  });
  linearOwners.set(reading,graph);
  return reading;
}

/**
 * Source-identified finite linear observations over the SAME admitted
 * Keratin/Feather graph and its original cellular sheaf, not another graph.
 *
 * Every candidate local value is a caller-supplied for/against witness
 * pair, evaluated through the ORIGINAL Data FOUR reading algebra; only
 * "held" (positive, not opposed) may enter a numerical cochain.
 * A pure mathematical cochain is defined on every stalk and the legacy
 * `cochain(sheaf, partialEntries)` intentionally zero-extends unspecified
 * coordinates. That law is NOT a license to treat UNOBSERVED source positions
 * as measured zeros. Here complete independent reports must exist for all
 * positive-dimensional stalks before we invoke the original cochain and
 * coboundary kernels. Incompatible source reports remain an obstruction with
 * their sources, never first/last-writer wins. A small numeric coboundary
 * measures conditional linear compatibility, not a FOUR settlement, true
 * physical strain, verified source attestation, or a witnessed causal Hole.
 */
export function assessKeratinLinearObservations(reading, observations, options={}) {
  if(!linearOwners.has(reading))
    fail('linear observations require the original in-process Keratin linear reading');
  const qualified=fields(options,['tolerance'],'linear observation options');
  const {tolerance=0}=qualified;
  if(typeof tolerance!=='number'||!Number.isFinite(tolerance)||tolerance<0)
    fail('linear observation tolerance must be a finite nonnegative number');
  if(!Array.isArray(observations)||observations.length>MAX_POSITIONS*8)
    fail('linear observations must be a bounded list of source-named values');
  sourceArray(observations,'linear observations',MAX_POSITIONS*8);
  const witnessLane=(values,side)=>{
    if(!Array.isArray(values)||values.length>64)
      fail('linear observation '+side+' testimony must be a bounded witness list');
    sourceArray(values,'linear observation '+side+' testimony requires material source identities',64);
    const names=[];
    for(let i=0;i<values.length;i++){
      const slot=Object.getOwnPropertyDescriptor(values,String(i));
      if(!slot||!Object.hasOwn(slot,'value')||!named(slot.value))
        fail('linear observation '+side+' testimony requires material source identities');
      names.push(slot.value);
    }
    unique(names,'linear observation '+side+' testimony');
    return frozen(names);
  };

  const sheaf=reading.sheaf;
  const byPosition=new Map(sheaf.vertices.map(vertex=>[vertex.id,[]]));
  for(const sourceObservation of observations) {
    const observation=fields(sourceObservation,['position','value','sourceRecord','evidence'],'linear observation');
    // Neither source identifiers nor values may execute getters. Sample each
    // caller-supplied source record once, before numerical interpretation.
    const own=key=>{
      const slot=Object.getOwnPropertyDescriptor(observation,key);
      if(!slot||!Object.hasOwn(slot,'value'))fail('linear observations require own data fields');
      return slot.value;
    };
    const position=own('position'),sourceRecord=own('sourceRecord');
    requireName(sourceRecord,'linear observation sourceRecord');
    const evidence=fields(own('evidence'),['for','against'],'linear evidence');
    const side=key=>{
      const slot=Object.getOwnPropertyDescriptor(evidence,key);
      if(!slot||!Object.hasOwn(slot,'value'))
        fail('linear observation evidence needs two material witness lanes');
      return witnessLane(slot.value,key);
    };
    const positive=side('for'),negative=side('against');
    const valuation=readingOfSides('extremal',positive.length>0,negative.length>0);
    const rows=byPosition.get(position);
    const vertex=sheaf.vertices.find(entry=>entry.id===position);
    if(rows===undefined||vertex===undefined)
      fail('linear observation names no original sheaf position');
    const value=own('value');
    // A sparse million-slot source is refused BEFORE Array.from allocates or
    // reads a source position. The original linear stalks are at most 16D.
    if(Array.isArray(value))
      sourceArray(value,'linear observation values require dense own data slots',16);
    const values=Array.isArray(value)
      ?Array.from({length:value.length},(_,i)=>{
        const slot=Object.getOwnPropertyDescriptor(value,String(i));
        if(!slot||!Object.hasOwn(slot,'value'))
          fail('linear observation values require dense own data slots');
        return slot.value;
      }):[value];
    if(values.length!==vertex.dim||values.some(v=>typeof v!=='number'||!Number.isFinite(v)))
      fail('linear observation needs complete finite numeric stalk coordinates');
    rows.push(freeze({sourceRecord,value:frozen(values),
      evidence:freeze({for:positive,against:negative}),reading:valuation}));
  }
  const positions=frozen(sheaf.vertices.map(vertex=>freeze({
    position:vertex.id,
    reports:frozen(byPosition.get(vertex.id)),
  })));
  const missingPositions=frozen(positions.filter(row=>row.reports.length===0).map(row=>row.position));
  const contestedPositions=frozen(positions.filter(row=>row.reports.some(report=>
    report.value.some((value,i)=>value!==row.reports[0].value[i]))).map(row=>freeze({
    position:row.position,
    reports:row.reports,
  })));
  const unqualifiedPositions=frozen(positions.filter(row=>row.reports.some(report=>
    report.reading!=='held')).map(row=>freeze({
    position:row.position,
    reports:row.reports.filter(report=>report.reading!=='held'),
  })));
  const complete=missingPositions.length===0&&contestedPositions.length===0&&
    unqualifiedPositions.length===0;
  if(!complete)return freeze({
    kind:'signgraph.keratinGraph.linearObservation.v1',
    status:'unassayed-incomplete-or-unqualified-source',
    positions,missingPositions,contestedPositions,unqualifiedPositions,
    vector:null,edgeResiduals:null,residualNorm:null,compatible:null,
    originalGraphOnly:true,sourceAuthentication:'caller-supplied-not-adjudicated',
    physicalInterpretation:'not-established',
  });
  // Reuse the ORIGINAL mathematical cochain/δ, after explicit complete
  // admission; this is never its implicit missing->0 extension.
  const vector=cochain(sheaf,positions.map(row=>({
    vertex:row.position,value:row.reports[0].value,
  })),{missing:'refuse'});
  const delta=apply(coboundary(sheaf),vector);
  const edgeResiduals=frozen(sheaf.edges.map((edge,i)=>{
    const values=delta.slice(sheaf.edgeOffsets[i],sheaf.edgeOffsets[i]+edge.dim);
    const residual=Math.hypot(...values);
    if(!Number.isFinite(residual))fail('linear observation numerical residual exceeds host arithmetic');
    const source=reading.sourceOccurrences.find(o=>o.occurrence===edge.id);
    return freeze({occurrence:edge.id,sourceRecord:source?.sourceRecord??null,
      values:frozen(values),norm:residual});
  }));
  const residualNorm=Math.hypot(...delta);
  if(!Number.isFinite(residualNorm))
    fail('linear observation numerical norm exceeds host arithmetic');
  const compatible=residualNorm<=tolerance;
  return freeze({
    kind:'signgraph.keratinGraph.linearObservation.v1',
    status:compatible?'compatible-numeric-coboundary':'incompatible-numeric-coboundary',
    positions,missingPositions,contestedPositions,unqualifiedPositions,
    vector:frozen(vector),edgeResiduals,residualNorm,compatible,tolerance,
    originalGraphOnly:true,sourceAuthentication:'caller-supplied-not-adjudicated',
    physicalInterpretation:'not-established',
  });
}

function solveSectionScopes(domains, constraints, {limit=DEFAULT_ASSIGNMENT_BUDGET,samples=2,visible=[]}={}) {
  const names=[...domains.keys()].sort(ordered);
  const product=names.reduce((n,key)=>n*BigInt(domains.get(key).length),1n);
  if (product>BigInt(limit)) return freeze({status:'not-evaluated: finite assignment budget exceeded',
    assignmentsUpperBound:String(product), count:null, examples:frozen([]), projections:null});
  const byTarget=new Map(names.map(key=>[key,[]]));
  const all=constraints.map(c=>({...c,table:new Set(c.allowed.map(p=>JSON.stringify(p)))}));
  for(const c of all) {
    byTarget.get(c.from)?.push(c);
    if(c.to!==c.from) byTarget.get(c.to)?.push(c);
  }
  const assign=new Map(), examples=[], projectionSets=visible.map(()=>new Set());
  let count=0;
  function dfs(i) {
    if(i===names.length) {
      count++;
      if(examples.length<samples)examples.push(freeze(Object.fromEntries(names.map(id=>[id,assign.get(id)]))));
      for(let o=0;o<visible.length;o++) projectionSets[o].add(JSON.stringify(visible[o].map(id=>assign.get(id))));
      return;
    }
    const key=names[i];
    for(const state of domains.get(key)) {
      assign.set(key,state);
      let fits=true;
      for(const c of byTarget.get(key)) {
        if(assign.has(c.from)&&assign.has(c.to)&&!c.table.has(JSON.stringify([assign.get(c.from),assign.get(c.to)]))) {
          fits=false;break;
        }
      }
      if(fits)dfs(i+1);
    }
    assign.delete(key);
  }
  dfs(0);
  return freeze({status:'exact', assignmentsUpperBound:String(product),count,
    examples:frozen(examples),projections:projectionSets});
}

/**
 * Exact finite feasibility on the model's supplied stalk/relation state tables.
 * Not a theorem proving biological locks; event-added exclusions are a
 * consumer-supplied monotone information restriction. Observer scopes are
 * explicit and cannot silently acquire a causal-cone interpretation.
 */
export function analyzeKeratinGraph(graph, options={}) {
  const qualified=fields(options,['maxAssignments'],'analysis options');
  const {maxAssignments=DEFAULT_ASSIGNMENT_BUDGET}=qualified;
  if(!admitted.has(graph))fail('analysis requires the original in-process generated reading');
  if(!Number.isSafeInteger(maxAssignments)||maxAssignments<1||maxAssignments>2000000)
    fail('analysis maxAssignments must be a positive safe number <= 2000000');
  const excluded=new Map(graph.stalks.map(s=>[s.position,new Set()]));
  for(const lock of graph.locks)for(const state of lock.excludes)excluded.get(lock.position).add(state);
  const domains=new Map(graph.stalks.map(s=>[s.position,s.states.filter(v=>!excluded.get(s.position).has(v))]));
  const reported=graph.observers.map(o=>[...o.visiblePositions].sort(ordered));
  const sections=solveSectionScopes(domains,graph.contacts,{limit:maxAssignments,visible:reported});
  const observers=graph.observers.map((o,i)=>{
    const scope=new Map(reported[i].map(p=>[p,domains.get(p)]));
    const visible=new Set(o.visibleOccurrences);
    const local=solveSectionScopes(scope,graph.contacts.filter(c=>visible.has(c.occurrence)),{limit:maxAssignments,samples:2});
    if(local.status!=='exact'||sections.status!=='exact')return freeze({
      id:o.id,status:'not-evaluated: finite assignment budget exceeded',
      observerQualification:o.qualification,localSections:local.count,globallyLiftableReports:null,
      unliftableLocalReports:null,examples:frozen([]),
    });
    // The observer's own compatible local assignments are not automatically
    // restrictions of any actual global assignment.
    const full=sections.projections[i];
    const projectedLocals=solveSectionScopes(scope,graph.contacts.filter(c=>visible.has(c.occurrence)),{
      limit:maxAssignments,samples:0,visible:[reported[i]],
    }).projections[0];
    const unliftable=[...projectedLocals].filter(signature=>!full.has(signature));
    return freeze({id:o.id,status:'exact',observerQualification:o.qualification,
      localSections:local.count,globallyLiftableReports:full.size,
      unliftableLocalReports:unliftable.length,
      examples:frozen(unliftable.slice(0,2).map(sig=>freeze(Object.fromEntries(reported[i].map((id,index)=>[id,JSON.parse(sig)[index]]))))),
    });
  });
  let conflictCore=null;
  const locallyEmpty=[...domains].filter(([,values])=>values.length===0).map(([id])=>id);
  if(sections.status==='exact'&&sections.count===0&&locallyEmpty.length===0&&graph.contacts.length<=32){
    let core=[...graph.contacts];
    for(const edge of graph.contacts) {
      const without=core.filter(item=>item.occurrence!==edge.occurrence);
      if(solveSectionScopes(domains,without,{limit:maxAssignments,samples:0}).count===0)core=without;
    }
    conflictCore=frozen(core.map(c=>c.occurrence));
  }
  const result=freeze({
    kind:'signgraph.keratinGraph.analysis.v1',
    sectionStatus:sections.status,
    sectionCount:sections.count,
    assignmentsUpperBound:sections.assignmentsUpperBound,
    sampleSections:sections.examples,
    localStalks:frozen([...domains].map(([position,states])=>freeze({position,
      permitted:frozen(states),excluded:frozen([...excluded.get(position)].sort(ordered))}))),
    unsatisfiableContactCore:conflictCore,
    emptyStalks:frozen(locallyEmpty),
    actualComplexBetti:graph.topology.betti,
    graphOnlyH1:graph.topology.graphOnlyH1,
    independentDeclaredUnfilledBoundaries:graph.aggregateIndependentBoundaries,
    candidateHoles:graph.candidateHoles,
    observers:frozen(observers),
    qualification:'exact finite model computation only; actual causal holes, physical material, and witnessed source generation remain unproved',
  });
  analysisOwners.set(result,graph);
  return result;
}

const dot = value => JSON.stringify(String(value));
/** Render a standard Graphviz DOT graph, with *annotation-only* hole/face glyphs. */
export function keratinGraphToDot(graph, analysis) {
  if(!admitted.has(graph))fail('Graphviz projection requires original generated keratin reading');
  if(analysis !== undefined && analysisOwners.get(analysis)!==graph)
    fail('Graphviz analysis must be an analysis receipt from this particular keratin graph');
  const nodes=graph.feather.positions;
  const nodeIndex=new Map(nodes.map((p,i)=>[p.key,`n${i}`]));
  const stalks=new Map(graph.stalks.map(s=>[s.position,s]));
  const allowed=new Map((analysis?.localStalks??[]).map(s=>[s.position,s]));
  const locked=new Map(nodes.map(p=>[p.key,[]]));
  for(const lock of graph.locks)locked.get(lock.position).push(lock.id);
  const claimedHoles=new Set(graph.candidateHoles.flatMap(h=>h.boundary.map(step=>step.edge)));
  const incompatible=new Set(analysis?.unsatisfiableContactCore??[]);
  const summary=analysis===undefined?'':'; topological H1='+analysis.actualComplexBetti.h1+
    '; finite section count='+(analysis.sectionCount===null?'not evaluated':analysis.sectionCount);
  const lines=['digraph KeratinGraph {',
    `  graph [label=${dot(`Keratin Graph: hole/sheaf reading${summary}`)},labelloc=t,rankdir=LR];`,
    '  node [shape=ellipse,fontname="Helvetica"];','  edge [fontname="Helvetica"];'];
  nodes.forEach((p,i)=>{
    const domain=allowed.get(p.key)?.permitted??stalks.get(p.key).states;
    const details=`${p.display??p.performed}\n${p.performed} (${p.side})\nstalk: ${domain.join(', ')}`+
      (locked.get(p.key).length?`\nlocks: ${locked.get(p.key).join(', ')}`:'');
    lines.push(`  n${i} [label=${dot(details)}];`);
  });
  const original=new Map(graph.feather.predications.map(p=>[p.occurrence,p]));
  graph.feather.predications.forEach((e,i)=>{
    const color=incompatible.has(e.occurrence)?'firebrick':claimedHoles.has(e.occurrence)?'royalblue':'gray45';
    lines.push(`  ${nodeIndex.get(e.subject)} -> ${nodeIndex.get(e.object)} [id=${dot(`e${i}`)}, label=${dot(`${e.predicate} [${e.occurrence}]`)}, tooltip=${dot(`Original source record: ${e.sourceRecord}`)}, color=${dot(color)}];`);
  });
  function annotate(id, boundary, label, color, shape){
    const touched=new Set();
    for(const step of boundary){const e=original.get(step.edge);touched.add(e.subject);touched.add(e.object);}
    lines.push(`  ${id} [shape=${shape},style=dashed,color=${color},label=${dot(label)}];`);
    // Dashed spokes locate an overlay and are not part of mathematical incidence.
    for(const position of touched)lines.push(`  ${id} -> ${nodeIndex.get(position)} [style=dotted,arrowhead=none,constraint=false,color=${color},label="annotation"];`);
  }
  graph.filledFaces.forEach((face,i)=>annotate(`face${i}`,face.boundary,`supplied 2-cell: ${face.id}\n(${face.sourceRecord})`, 'seagreen','box'));
  graph.candidateHoles.forEach((hole,i)=>annotate(`hole${i}`,hole.boundary,
    `candidate boundary: ${hole.id}\n${hole.reading}\n(no supplied face)`, 'royalblue','diamond'));
  lines.push('}');
  return lines.join('\n')+'\n';
}
